SELECT (b.Capacity * 20.0) + (h.Capacity * 5.5) AS total_money
FROM stadium b, stadium h
WHERE b.Name = 'Balmoor' AND h.Name = 'Hampden Park';

SELECT (COUNT(*) * 100.0 / (SELECT COUNT(*) FROM concert)) AS percentage
FROM concert
WHERE Stadium_ID IN (
  SELECT Stadium_ID FROM stadium ORDER BY Average DESC LIMIT 3
);

SELECT Name, GNPOld AS past_GNP, GNP AS current_GNP, GNP * GNP / NULLIF(GNPOld, 0) AS future_GNP
FROM country
WHERE Continent = 'Asia';

SELECT ROUND(Population * 1.004) AS population_one_year_later
FROM country
WHERE Name = 'United Kingdom';

SELECT IndepYear + CASE WHEN (GNP * 1.0 / Population) > (SELECT AVG(GNP * 1.0 / Population) FROM country WHERE Continent = 'Europe' AND GNP IS NOT NULL AND Population > 0) THEN LifeExpectancy + 10 ELSE LifeExpectancy END
FROM country
WHERE Name = 'Zambia';
